{
  "packet_id": "H7-T03-1",
  "candidates": [
    {
      "candidate_id": "K01",
      "component": {
        "component_id": "K01.main",
        "value": "Recorded order dates provide calendar anchors. During alignment, keep known dates fixed, preserve event order, and shift only uncertain recalled segments within their reported date ranges.",
        "scope": "Prospective restrictions on permissible adjustments; neither uncertain recollections nor informative alignment are asserted to exist. Individual anchor reliability remains unestablished.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C001, C010–C012 supply the surviving restrictions. Their structural warrant does not establish the empirical conditions needed for useful alignment.",
          "evidence_used": [
            {"source_id": "P002"},
            {"source_id": "P009"},
            {"source_id": "P010"},
            {"source_id": "T001"},
            {"source_id": "S002"}
          ]
        }
      },
      "surviving_claim_ids": ["C001", "C010", "C011", "C012"],
      "kind": "TARGET_CONSTRAINT",
      "unit_id": "",
      "viability": {
        "warranted": {"value": "YES", "rationale": "Warranted as restrictions on any proposed adjustment, not as unconditional permission for diagnostically useful shifting."},
        "source_derived": {"value": "YES", "rationale": "Preserves independent temporal anchors and ordered-pattern comparison from S002."},
        "target_relevant": {"value": "YES", "rationale": "Constrains reconstruction of customer histories relevant to the ordering of need and service encounters."},
        "productive": {"value": "YES", "rationale": "Excludes adjustments that move known dates, reorder events, or exceed reported ranges."},
        "material": {"value": "YES", "rationale": "These exclusions materially change which reconstructions are admissible."}
      },
      "counterfactual_target_change": "Removing the whole unit removes these explicit admissibility restrictions, without establishing that any alternative reconstruction is true.",
      "counterfactual_inquiry_change": "History comparison loses its fixed-anchor, order-preservation and bounded-shift requirements."
    },
    {
      "candidate_id": "K02",
      "component": {
        "component_id": "K02.main",
        "value": "Comparable consumption and a common response to shared service conditions are not established.",
        "scope": "Cross-household comparisons; neither incomparability nor differing responses is established.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C006 and C007 survive as statements of missing support.",
          "evidence_used": [
            {"source_id": "P004"},
            {"source_id": "T001"}
          ]
        }
      },
      "surviving_claim_ids": ["C006", "C007"],
      "kind": "INSUFFICIENCY_ONLY",
      "unit_id": "",
      "viability": {
        "warranted": {"value": "YES", "rationale": "The target leaves consumption and explanations unresolved."},
        "source_derived": {"value": "YES", "rationale": "Identifies the unestablished target counterpart of the source's shared temporal influence."},
        "target_relevant": {"value": "YES", "rationale": "Concerns applicability of cross-household alignment."},
        "productive": {"value": "NO", "rationale": "The unit supplies no selected operation or additional actual constraint beyond missing establishment."},
        "material": {"value": "NO", "rationale": "Removing this statement does not supply the missing bridge or change the surviving conditional licenses."}
      },
      "counterfactual_target_change": "No justified positive assumption of comparable consumption or common response becomes available.",
      "counterfactual_inquiry_change": "An explicit insufficiency statement disappears; no independent inquiry branch is lost."
    },
    {
      "candidate_id": "K03",
      "component": {
        "component_id": "K03.main",
        "value": "Preserve unknown intervals as unknown and distinguish reported events from recorded orders.",
        "scope": "Construction and comparison of histories; no actual unknown interval or general reliability ranking is asserted.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C008 and C009 provide prospective representation requirements.",
          "evidence_used": [
            {"source_id": "P008"},
            {"source_id": "S001"},
            {"source_id": "S002"}
          ]
        }
      },
      "surviving_claim_ids": ["C008", "C009"],
      "kind": "TARGET_CONSTRAINT",
      "unit_id": "",
      "viability": {
        "warranted": {"value": "YES", "rationale": "The representation requirements are coherent without asserting that their triggers have occurred."},
        "source_derived": {"value": "YES", "rationale": "Maintains the distinction between anchored observations and unresolved temporal information needed by the source comparison."},
        "target_relevant": {"value": "YES", "rationale": "Customer reconstructions combine records and reports."},
        "productive": {"value": "YES", "rationale": "Changes the required representation and evidential labeling of histories."},
        "material": {"value": "YES", "rationale": "Prevents unknown intervals and reports from silently acquiring recorded-order status."}
      },
      "counterfactual_target_change": "The explicit representation and provenance requirements disappear.",
      "counterfactual_inquiry_change": "Comparison no longer carries this requirement to preserve unknown intervals and distinguish evidence types."
    },
    {
      "candidate_id": "K04",
      "component": {
        "component_id": "K04.main",
        "value": "Compare permissible alternative alignments and record competing fits. A distinctive, independently corroborated calendar alignment can narrow event timing, check histories and connect supported overlaps; equally plausible alternatives require stopping alignment.",
        "scope": "Conditional chronology inquiry. Shared calendar correspondence, reliable independent anchors, informative overlap and corroboration are prerequisites for the positive branch; none is established to occur.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C013, C014, C020 and C033–C035 supply the contrast, comparison and differential consequences. Duplicate formulations in operation, signal and inference are merged.",
          "evidence_used": [
            {"source_id": "P009"},
            {"source_id": "P010"},
            {"source_id": "P014"},
            {"source_id": "P018"},
            {"source_id": "P019"},
            {"source_id": "P025"},
            {"source_id": "S002"},
            {"source_id": "S003"},
            {"source_id": "S004"},
            {"source_id": "S005"}
          ]
        }
      },
      "surviving_claim_ids": ["C013", "C014", "C020", "C033", "C034", "C035"],
      "kind": "INQUIRY_CONSTRAINT",
      "unit_id": "U01",
      "viability": {
        "warranted": {"value": "YES", "rationale": "Comparison and the tie-stop rule are warranted; temporal conclusions are warranted only under the stated qualifying conditions."},
        "source_derived": {"value": "YES", "rationale": "Directly preserves ordered alignment, checking chronology and sensitivity to ambiguous fits."},
        "target_relevant": {"value": "YES", "rationale": "Can resolve or expose unresolved customer-event ordering relevant to explanations of nonpurchase."},
        "productive": {"value": "YES", "rationale": "Selects comparison and distinguishes conditional temporal inference from stopping on a tie."},
        "material": {"value": "YES", "rationale": "Changes both admissible chronological conclusions and whether alignment continues."}
      },
      "counterfactual_target_change": "Removing the entire unit removes the conditional route to temporal narrowing, history checking and linkage through alignment.",
      "counterfactual_inquiry_change": "The alternative-fit comparison and its positive-versus-tied decision branches disappear together."
    },
    {
      "candidate_id": "K05",
      "component": {
        "component_id": "K05.main",
        "value": "Test uncertain collection recollections against the proposed ordered sequence of low stock, unsuccessful collection and a later or delayed order recurring around the same service conditions.",
        "scope": "Illustrative alignment test only. Distinctive shared calendar correspondence must be available; calling an order delayed additionally requires evidence of need or an expected interval.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C015 preserves this proposed sequence, with conditional operational license and no observed finding.",
          "evidence_used": [
            {"source_id": "P011"},
            {"source_id": "P020"},
            {"source_id": "P021"},
            {"source_id": "S002"},
            {"source_id": "S003"},
            {"source_id": "S005"},
            {"source_id": "T001"}
          ]
        }
      },
      "surviving_claim_ids": ["C015"],
      "kind": "TARGET_CONSTRAINT",
      "unit_id": "U02",
      "viability": {
        "warranted": {"value": "YES", "rationale": "Conditionally warranted as an illustrative test, without assuming a shared signal, actual recurrence or delay."},
        "source_derived": {"value": "YES", "rationale": "Specifies ordered-pattern comparison against independently constrained temporal histories."},
        "target_relevant": {"value": "YES", "rationale": "Focuses comparison on the temporal relationship between stock need and collection difficulty."},
        "productive": {"value": "YES", "rationale": "Supplies a specific sequence to test within the conditional alignment procedure."},
        "material": {"value": "YES", "rationale": "Its removal leaves general alignment without this concrete collection-related comparison."}
      },
      "counterfactual_target_change": "No established customer finding is removed.",
      "counterfactual_inquiry_change": "The specific low-stock/failed-collection/later-order test disappears; no replacement signal is inferred."
    },
    {
      "candidate_id": "K06",
      "component": {
        "component_id": "K06.main",
        "value": "Supplement calendar comparisons with time since first order and time since reported depletion, without replacing calendar dates.",
        "scope": "Auxiliary comparison only; depletion must be sufficiently dated, and elapsed-time similarity cannot independently assign calendar positions.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C017 survives with these conditional limits.",
          "evidence_used": [
            {"source_id": "P012"},
            {"source_id": "S002"},
            {"source_id": "S004"},
            {"source_id": "S005"},
            {"source_id": "T001"}
          ]
        }
      },
      "surviving_claim_ids": ["C017"],
      "kind": "TARGET_CONSTRAINT",
      "unit_id": "",
      "viability": {
        "warranted": {"value": "YES", "rationale": "Warranted only as the stated conditional supplementary comparison."},
        "source_derived": {"value": "YES", "rationale": "Preserves the source distinction between actual calendar correspondence and merely similar sequence stages."},
        "target_relevant": {"value": "YES", "rationale": "Purchase age and depletion age bear on differing purchase intervals."},
        "productive": {"value": "YES", "rationale": "Adds auxiliary temporal comparisons while retaining calendar anchors."},
        "material": {"value": "YES", "rationale": "Changes how household-stage similarity may inform the inquiry."}
      },
      "counterfactual_target_change": "No actual depletion date or consumption estimate is lost.",
      "counterfactual_inquiry_change": "The selected auxiliary comparisons and the restriction against substituting them for calendar comparison disappear."
    },
    {
      "candidate_id": "K07",
      "component": {
        "component_id": "K07.main",
        "value": "Treat apparent missing or anomalous episodes as questions for corroboration. Seek clarification of an omission-suggesting mismatch through already agreed follow-up, and never insert an event merely to improve alignment.",
        "scope": "Conditional response to an observed mismatch; no omission, follow-up success or recovered event is asserted.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C018 and C019 provide an actual clarification operation and a prohibition on unsupported insertion.",
          "evidence_used": [
            {"source_id": "P013"},
            {"source_id": "P022"},
            {"source_id": "S003"},
            {"source_id": "S004"},
            {"source_id": "S005"},
            {"source_id": "T001"}
          ]
        }
      },
      "surviving_claim_ids": ["C018", "C019"],
      "kind": "TARGET_CONSTRAINT",
      "unit_id": "U03",
      "viability": {
        "warranted": {"value": "YES", "rationale": "The mismatch licenses clarification, not an inference that an event was omitted."},
        "source_derived": {"value": "YES", "rationale": "Transfers anomaly checking while respecting false-alignment risk."},
        "target_relevant": {"value": "YES", "rationale": "Clarification can affect the evidential basis of customer-history explanations."},
        "productive": {"value": "YES", "rationale": "Selects agreed clarification and excludes insertion solely for fit."},
        "material": {"value": "YES", "rationale": "Changes the response to mismatches and permissible revisions."}
      },
      "counterfactual_target_change": "The explicit requirement to keep suspected episodes unestablished pending corroboration disappears.",
      "counterfactual_inquiry_change": "The clarification response and prohibition on fit-driven event insertion disappear together."
    },
    {
      "candidate_id": "K08",
      "component": {
        "component_id": "K08.main",
        "value": "Stop alignment when the first week ends.",
        "scope": "Operational time bound, regardless of whether an explanation has been discriminated.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C022 supplies the surviving deadline; no other stopping clause in its containing span is imported.",
          "evidence_used": [
            {"source_id": "P014"},
            {"source_id": "T001"}
          ]
        }
      },
      "surviving_claim_ids": ["C022"],
      "kind": "TARGET_CONSTRAINT",
      "unit_id": "",
      "viability": {
        "warranted": {"value": "YES", "rationale": "The prospective deadline has a determinate trigger and response."},
        "source_derived": {"value": "NO", "rationale": "A one-week allocation comes from target scheduling, not the chronology mechanism."},
        "target_relevant": {"value": "YES", "rationale": "Bounds work before the five-week purchasing commitment."},
        "productive": {"value": "YES", "rationale": "Requires stopping even when further alignment might be attempted."},
        "material": {"value": "YES", "rationale": "Changes the permitted duration of inquiry."}
      },
      "counterfactual_target_change": "The five-week target deadline remains.",
      "counterfactual_inquiry_change": "The separate first-week alignment deadline disappears."
    },
    {
      "candidate_id": "K09",
      "component": {
        "component_id": "K09.main",
        "value": "Specify the selected process change's intended observable effect in advance.",
        "scope": "A requirement if a process change is selected; no selection, effect size or success threshold is supplied.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C026 survives independently of deleted trial-selection and allocation operations.",
          "evidence_used": [{"source_id": "P016"}]
        }
      },
      "surviving_claim_ids": ["C026"],
      "kind": "TARGET_CONSTRAINT",
      "unit_id": "U05",
      "viability": {
        "warranted": {"value": "YES", "rationale": "Coherent prospective specification requirement."},
        "source_derived": {"value": "NO", "rationale": "Trial-effect prespecification is not an operation of temporal alignment."},
        "target_relevant": {"value": "YES", "rationale": "Relevant to interpreting a bounded process trial."},
        "productive": {"value": "YES", "rationale": "Requires an observable intended effect before evaluation."},
        "material": {"value": "YES", "rationale": "Constrains the timing and content of trial specification."}
      },
      "counterfactual_target_change": "No effect or trial result is removed.",
      "counterfactual_inquiry_change": "The advance-specification requirement disappears; a trial design is still not supplied."
    },
    {
      "candidate_id": "K10",
      "component": {
        "component_id": "K10.main",
        "value": "If no explanation is sufficiently discriminated, refrain from choosing a purported remedy.",
        "scope": "Inconclusive-inquiry branch; sufficient discrimination has no numerical threshold.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C028 specifies actual abstention, not merely an insufficiency statement.",
          "evidence_used": [
            {"source_id": "P017"},
            {"source_id": "S004"},
            {"source_id": "S005"},
            {"source_id": "T001"}
          ]
        }
      },
      "surviving_claim_ids": ["C028"],
      "kind": "TARGET_CONSTRAINT",
      "unit_id": "",
      "viability": {
        "warranted": {"value": "YES", "rationale": "The conditional abstention rule is coherent without claiming that inquiry is already inconclusive."},
        "source_derived": {"value": "YES", "rationale": "Applies the source's ambiguous-alignment limit to the permissible use of the resulting evidence."},
        "target_relevant": {"value": "YES", "rationale": "Directly constrains the requested bounded service decision."},
        "productive": {"value": "YES", "rationale": "Selects abstention from a purported remedy under the stated trigger."},
        "material": {"value": "YES", "rationale": "Changes what the team may claim to select following inconclusive inquiry."}
      },
      "counterfactual_target_change": "The explicit abstention branch disappears; no remedy thereby becomes evidenced.",
      "counterfactual_inquiry_change": "Inconclusiveness no longer carries this particular decision consequence."
    },
    {
      "candidate_id": "K11",
      "component": {
        "component_id": "K11.main",
        "value": "Meet the purchasing deadline using confirmed demand, stock and usage information, available trial results and explicit uncertainty. If explanations remain unresolved, make a cautious, explicitly uncertain commitment from confirmed orders and reported stock needs.",
        "scope": "Five-week purchasing governance. Inputs and credible trial results are not asserted to exist; quantities and weights remain unspecified.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C029 and C040 express the general purchasing basis and its unresolved-explanation branch. C040's conditional dependence does not establish usable trial results.",
          "evidence_used": [
            {"source_id": "P017"},
            {"source_id": "P029"},
            {"source_id": "T001"}
          ]
        }
      },
      "surviving_claim_ids": ["C029", "C040"],
      "kind": "TARGET_CONSTRAINT",
      "unit_id": "",
      "viability": {
        "warranted": {"value": "YES", "rationale": "Warranted as prospective decision governance, not as support for any purchase quantity or the availability of valid trial findings."},
        "source_derived": {"value": "NO", "rationale": "Purchasing inputs and deadline management are target decision requirements, not consequences supplied by chronology alignment."},
        "target_relevant": {"value": "YES", "rationale": "Directly addresses the purchasing commitment."},
        "productive": {"value": "YES", "rationale": "Prescribes proceeding under unresolved uncertainty with named evidence inputs."},
        "material": {"value": "YES", "rationale": "Changes the required basis and uncertainty disclosure of the commitment."}
      },
      "counterfactual_target_change": "The purchasing deadline remains, but the explicit evidence-basis and fallback instructions disappear.",
      "counterfactual_inquiry_change": "The inquiry loses its specified handoff to purchasing under uncertainty."
    },
    {
      "candidate_id": "K12",
      "component": {
        "component_id": "K12.main",
        "value": "Record participation and missing follow-up separately from outcomes.",
        "scope": "Inquiry and trial records; no particular participation measure or missing-data analysis is prescribed.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C031 and C032 supply separate recording requirements.",
          "evidence_used": [{"source_id": "P024"}]
        }
      },
      "surviving_claim_ids": ["C031", "C032"],
      "kind": "TARGET_CONSTRAINT",
      "unit_id": "",
      "viability": {
        "warranted": {"value": "YES", "rationale": "Both recording rules have determinate prospective responses."},
        "source_derived": {"value": "NO", "rationale": "Participation and follow-up status are study-record distinctions not supplied by the source alignment mechanism."},
        "target_relevant": {"value": "YES", "rationale": "Relevant to limited voluntary follow-up."},
        "productive": {"value": "YES", "rationale": "Changes required record structure."},
        "material": {"value": "YES", "rationale": "Keeps missingness and participation from being recorded as substantive outcomes."}
      },
      "counterfactual_target_change": "No customer outcome changes, but these explicit evidential categories disappear.",
      "counterfactual_inquiry_change": "Separate participation and missing-follow-up recording is no longer required by the remainder."
    },
    {
      "candidate_id": "K13",
      "component": {
        "component_id": "K13.main",
        "value": "A qualifying alignment can help distinguish some households without refill need from households whose need preceded a documented obstacle.",
        "scope": "Only households with independently corroborated need or absence of need and sufficiently resolved event ordering. No actual classification, causation or population explanation follows.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C036 preserves the conditional distinction. Its lineage requires household-specific evidence independent of temporal matching; neither a data-collection operation nor a stock-availability signal is restored.",
          "evidence_used": [
            {"source_id": "P025"},
            {"source_id": "P026"},
            {"source_id": "S004"},
            {"source_id": "S005"},
            {"source_id": "T001"}
          ]
        }
      },
      "surviving_claim_ids": ["C036"],
      "kind": "POSITIVE_INFERENCE",
      "unit_id": "U02",
      "viability": {
        "warranted": {"value": "YES", "rationale": "Warranted only under the independent-need-evidence and resolved-ordering conditions; alignment alone is insufficient."},
        "source_derived": {"value": "YES", "rationale": "Temporal placement supplies the ordering contribution within the explicitly conditional distinction."},
        "target_relevant": {"value": "YES", "rationale": "Separates two live explanations for missing second orders."},
        "productive": {"value": "YES", "rationale": "Specifies a narrower household-level distinction that qualifying combined evidence could justify."},
        "material": {"value": "YES", "rationale": "Changes the permitted interpretation of informative histories without claiming population attribution."}
      },
      "counterfactual_target_change": "The explicit conditional route from resolved timing and independent need evidence to this household distinction disappears.",
      "counterfactual_inquiry_change": "Generic chronology comparison remains, but this stated explanatory use is lost."
    },
    {
      "candidate_id": "K14",
      "component": {
        "component_id": "K14.main",
        "value": "Repeated correspondence supports prioritizing a mechanism for a bounded trial.",
        "scope": "Retained conditional claim C037. Corroborated evidence must discriminate an actionable mechanism, and alternative alignments and explanations must be assessed; repeated timing alone does not suffice.",
        "provenance": {
          "support_status": "UNCERTAIN",
          "rationale": "C037 survives, but its operational bridge remains unestablished. The lineage's reference to P015 cannot supply the deleted intervention-selection propositions.",
          "evidence_used": [
            {"source_id": "P027"},
            {"source_id": "S004"},
            {"source_id": "S005"},
            {"source_id": "T001"}
          ]
        }
      },
      "surviving_claim_ids": ["C037"],
      "kind": "UNCERTAIN",
      "unit_id": "U05",
      "viability": {
        "warranted": {"value": "UNCERTAIN", "rationale": "Chronology correspondence alone does not warrant mechanism priority; the additional discriminating bridge is unresolved."},
        "source_derived": {"value": "UNCERTAIN", "rationale": "Alignment can inform timing, but mechanism selection requires additional evidence whose adequacy is not established."},
        "target_relevant": {"value": "YES", "rationale": "Mechanism prioritization bears on the bounded trial decision."},
        "productive": {"value": "UNCERTAIN", "rationale": "It would change trial priority if its bridge were supported; no present justified priority is supplied."},
        "material": {"value": "UNCERTAIN", "rationale": "Potentially consequential, but no warranted priority can presently be attributed to it."}
      },
      "counterfactual_target_change": "A conditional prioritization proposal disappears; no established preferred mechanism is lost.",
      "counterfactual_inquiry_change": "The suggested transition from chronology correspondence to trial priority disappears, while the bridge remains unresolved."
    },
    {
      "candidate_id": "K15",
      "component": {
        "component_id": "K15.main",
        "value": "Repeated correspondence does not establish that a prioritized mechanism explains the overall repeat-purchase decline.",
        "scope": "Population-level explanatory reach; no observed correspondence is assumed.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C038 states the evidential insufficiency of correspondence for population attribution.",
          "evidence_used": [
            {"source_id": "P027"},
            {"source_id": "S004"},
            {"source_id": "T001"}
          ]
        }
      },
      "surviving_claim_ids": ["C038"],
      "kind": "INSUFFICIENCY_ONLY",
      "unit_id": "",
      "viability": {
        "warranted": {"value": "YES", "rationale": "Temporal correspondence does not establish population causal attribution."},
        "source_derived": {"value": "YES", "rationale": "Accurately identifies the explanatory reach of chronology checking."},
        "target_relevant": {"value": "YES", "rationale": "Concerns explanation of the overall decline."},
        "productive": {"value": "NO", "rationale": "Adds no actual operation or decision constraint beyond non-establishment."},
        "material": {"value": "NO", "rationale": "Removing it does not enlarge the justified scope of surviving conditional claims."}
      },
      "counterfactual_target_change": "Population attribution remains unsupported.",
      "counterfactual_inquiry_change": "No selected operation or differential outcome branch disappears."
    },
    {
      "candidate_id": "K16",
      "component": {
        "component_id": "K16.main",
        "value": "A credible comparison during the month can support a provisional process decision within the tested group and conditions.",
        "scope": "Conditional on a decision-relevant within-month outcome and adequate handling of confounding, missing outcomes and uncertainty. Neither a credible comparison nor an eight-week effect is established.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C039 survives as a conditional inference. Its hypothetical credibility condition can be represented without importing deleted allocation or outcome-observation operations.",
          "evidence_used": [
            {"source_id": "P028"},
            {"source_id": "P036"},
            {"source_id": "T001"}
          ]
        }
      },
      "surviving_claim_ids": ["C039"],
      "kind": "POSITIVE_INFERENCE",
      "unit_id": "U05",
      "viability": {
        "warranted": {"value": "YES", "rationale": "Warranted only as the stated conditional consequence of an independently credible comparison."},
        "source_derived": {"value": "NO", "rationale": "Intervention comparison supplies this inference; temporal alignment does not."},
        "target_relevant": {"value": "YES", "rationale": "Addresses the limited process decision."},
        "productive": {"value": "YES", "rationale": "Specifies the provisional, local decision that qualifying comparison evidence could support."},
        "material": {"value": "YES", "rationale": "Defines a meaningful decision scope, although no current trial conclusion exists."}
      },
      "counterfactual_target_change": "The explicit conditional license for a local provisional process decision disappears.",
      "counterfactual_inquiry_change": "No implemented comparison is lost; the surviving packet still lacks its specific selected trial operation."
    },
    {
      "candidate_id": "K17",
      "component": {
        "component_id": "K17.main",
        "value": "Household differences and local events can disrupt shared patterns; short or repetitive sequences, recall or measurement errors, incorrect anchors, insufficient overlap and many searched shifts can create false matches. Claim no date precision beyond the supported range and extend no chronology beyond supported overlaps.",
        "scope": "Reliability and explicit conclusion bounds for alignment. No listed error, disturbance or false match is asserted to have occurred; thresholds and magnitudes remain unspecified.",
        "provenance": {
          "support_status": "SUFFICIENT",
          "rationale": "C042–C047 supply possible failure mechanisms; C048 and C049 supply actual precision and reach constraints. The warning list is not treated as independently productive, and no insufficient-overlap stopping rule is restored.",
          "evidence_used": [
            {"source_id": "P031"},
            {"source_id": "P032"},
            {"source_id": "P033"},
            {"source_id": "S002"},
